import{_ as o,o as c,c as d,a2 as s}from"./chunks/framework.xCjF2uVY.js";const h=JSON.parse('{"title":"数据流与构建","description":"资产怎么从 ROM 解出来、怎么编成 ROM、截图怎么自证机位","frontmatter":{"title":"数据流与构建","description":"资产怎么从 ROM 解出来、怎么编成 ROM、截图怎么自证机位"},"headers":[],"relativePath":"pipeline.md","filePath":"pipeline.md","lastUpdated":null}'),a={name:"pipeline.md"};function n(t,e,p,i,l,r){return c(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="数据流与构建" tabindex="-1">数据流与构建 <a class="header-anchor" href="#数据流与构建" aria-label="Permalink to &quot;数据流与构建&quot;">​</a></h1><p>本页正文由 <code>tools/gen_site.py</code> 从 <code>docs/scene-port.md</code> §1–§3 原样搬来(唯一上游在那份文档里)。更长的设计蓝图在 <code>docs/architecture.md</code>,预算与可行性在 <code>docs/feasibility.md</code>,工具链在 <code>docs/toolchain.md</code>。</p><h2 id="_1-范围" tabindex="-1">1. 范围 <a class="header-anchor" href="#_1-范围" aria-label="Permalink to &quot;1. 范围&quot;">​</a></h2><p>批准的终点是**「一个房间可自由走动探索（裁剪版）」**，具体到本场景 = 静态场景 + 幻影加农本体（静态网格）</p><ul><li>Link 可行走。<strong>不做</strong>：跨房间 exit、水/WaterBox、boss AI 与战斗、bgCam 分区变相机（本轮固定相机 + D-pad 手控）、N64 原版参考截图管线。</li></ul><p>本体身份钉死过一条误判：<code>object_sst</code> 是 Bongo Bongo（影之神殿），幻影加农是 actor type <code>0x52</code> → <code>object_gnd</code>，Standard 骨架（不是 Flex）⇒ 运行时 FK 不在本场景的依赖里。</p><h2 id="_2-数据流" tabindex="-1">2. 数据流 <a class="header-anchor" href="#_2-数据流" aria-label="Permalink to &quot;2. 数据流&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>external/oot/build/OoT.bin (ROM 权威镜像)</span></span>
<span class="line"><span>   ├─ tools/room_extract.py      → data/moribossroom_room_{0,1}.json   (DL 走查: 顶点/三角形/纹理描述符/剔除位)</span></span>
<span class="line"><span>   ├─ tools/col_extract.py       → include/scene/col_mori.h            (地板/墙/天花板多边形, 分类阈值 NY_STEEP=16384)</span></span>
<span class="line"><span>   ├─ tools/scene_cmds.py        → include/scene/env_mori.h            (灯光/雾/PLAYER_ENTRY)</span></span>
<span class="line"><span>   ├─ tools/boss_extract.py      → include/scene/boss_gnd.h            (本体刚体网格)</span></span>
<span class="line"><span>   └─ scripts/room_tex_decode.py → include/tex_room/*.h                (CI8 → A1B5G5R5, 描述符只从 DL 解, XML 里没有纹理)</span></span>
<span class="line"><span>                data/*.json ── scripts/room_extract_c.py ─→ include/scene/room_mori_r{0,1}.h</span></span>
<span class="line"><span>                ROM 侧: src_scene/{main.c, draw_room.c, collision.c, link_rigid.c, draw_boss.c} + include/room_gpu.h</span></span></code></pre></div><p>房间文件本身就是场景命令表（无固定头），顶点在房间内已是世界坐标（<code>G_MTX</code> 计数 = 0），因此不需要房间矩阵， 也不需要角色侧那套段 0x0D Mtx 槽。段内寻址掩码是 <code>&amp; 0xFFFFFF</code>（段 3）——<code>scripts/f3dex2_extract.py</code> 旧写法 <code>&amp; 0x1FFFFFF</code> 只对偶数段侥幸正确，已修并回归。</p><h2 id="_3-构建" tabindex="-1">3. 构建 <a class="header-anchor" href="#_3-构建" aria-label="Permalink to &quot;3. 构建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make -s                                        # 默认: 角色 ROM link_full_render.nds (锚定 8a546db4)</span></span>
<span class="line"><span>make -s SCENE=moribossroom WALK=1 BOSS=1 \\</span></span>
<span class="line"><span>     STARTX=15 STARTZ=-2900 CAMYAW=0.0 CAMPITCH=-5.0     # 验收 ROM moribossroom_render.nds (锚定 dd9bfa50)</span></span></code></pre></div><p><code>SCENE=</code> 非空时 Makefile 把 <code>SOURCEDIRS</code> 切到 <code>src_scene/</code>（<code>src/</code> 与 <code>src_scene/</code> 各有一个 <code>main()</code>， 混在一起必然重定义）。默认构建行为不受场景侧任何改动影响。</p><p>诊断旋钮（全部经 Makefile 白名单转发，不传即预处理后源码不变）： <code>ROOM=</code>（只画某间）<code>ROOMS=0</code>（一间也不画 ⇒ 清屏色变洋红，&quot;非洋红像素&quot;就是本体/角色的剪影， 本体门的实机侧就这么取）<code>ROOMTEX=0</code>（无纹理孪生）<code>LINKDRAW=0</code> <code>BOSS=0</code> <code>WIREFRAME=1</code>（按部位上色线框） <code>LAYER=</code>/<code>XLUB=</code>（opa/xlu 分层）<code>TRICOLOR=</code>/<code>TEXONLY=</code>/<code>TEXRAMP=</code> <code>LINKBBOX=1</code>（印 Link 投影包围盒） <code>VRAMMAP=1</code>（印纹理显存占用表）<code>PROJDUMP=1</code>（回读硬件投影矩阵，desmume 上不响应） <code>PERSP=</code>/<code>YAW=</code>/<code>PITCH=</code>/<code>ZOOM=</code>/<code>EYEX|Y|Z=</code>（正交诊断机位）<code>CAMDIST=</code>/<code>CAMH=</code>/<code>STEP=</code>/<code>LINKYAW0=</code><code>LINKSCL=</code>/<code>LINKCULL=</code>/<code>BOSSSCL=</code>/<code>BOSSCULL=</code>/<code>RAMSTAT=</code>。</p><p>抓图与按键驱动在截图脚本侧： <code>SCREEN=top|sub|both bash tools/capture_screen.sh &lt;rom&gt; &lt;out.png&gt;</code>（<code>both</code> 把<strong>同一张</strong>整窗图裁两次，副屏落 <code>SUB_OUT=</code>，默认 <code>&lt;out 去扩展名&gt;_sub.png</code>），环境变量 <code>KEYS=&#39;Up=45,Right=2&#39;</code>（依次按住 N 秒）、 <code>SETTLE=</code>（副屏文字每 30 帧才刷新，键盘图至少 12）。 <strong>键盘驱动的图必须 <code>SCREEN=both</code></strong>：<code>--disable-limiter</code> 下&quot;按住 N 秒&quot;走多远随机器负载变（实测同一条 KEYS 四次落在 z −3003/−2997/−3054/−2988，三下短按 A 只收到 2 下），top 与 sub 分两次跑就是两次不同的会话 ⇒ 读数描述的不是那张画面，编译期孪生必然对不上（本轮真那样 FAIL 过四轮）。<code>both</code> 保证画面与读数同一瞬间， 之后 <code>bash tools/walk_pose_proof.sh</code> 自己读数、按读数建孪生、逐字节比（0/49152 才算这张行走图的站位机位被证明）。</p><p><strong>变体纪律</strong>：blocksds 的 Makefile 只转发上面这些白名单变量，且 CFLAGS 不是 make 依赖 —— 每个变体必须 <code>rm -rf build/&lt;NAME&gt;</code> 后单独传 <code>NAME=</code>，并且<strong>先核对产物 md5 变了</strong>再看它的输出。历史上踩过一次：加了 <code>PROJDUMP</code> 却忘了加转发行，镜像与上一个变体逐位相同，打印从未生效。</p><p><strong>发布</strong>：站上只有两个目的地，且都从同一份上游生成，没有第三份手抄。Qoder Site 走 <code>base:&#39;/&#39;</code>（私有， <code>web/site/dist/</code>）。GitHub Pages 是<strong>子路径</strong>部署，所以用 <code>SITE_BASE=/nds-site/ npm run docs:build</code> 单独构建一份： 该环境变量同时把 <code>cleanUrls</code> 关掉 —— Pages 只认实体文件，<code>/nds-site/progress</code> 这种无扩展名 URL 必然 404， 只有 <code>.html</code> 形式能用。这份产物推到公开仓库 <code>adam-ikari/nds-site</code>（只有构建物 + <code>.nojekyll</code>， 无源码、无 ROM、无 <code>external/</code>），仓库必须 <code>private:false</code> —— 免费 plan 的私有仓库开不了 Pages。 两个目的地互不污染，判的是<strong>导航与资源 URL</strong> 而不是字符串本身（正文要提这个前缀，裸 <code>grep</code> 必然自己抓自己）： 私有站那份 dist 的 7 个 html 里 <code>&quot;/nds-site/</code> 形式命中 0，子路径构建里 7 个 html 全部带前缀， 量具 <code>python3 tools/gen_site.py --check-dist</code>（夹具：正例含一句正文提及 + 一条把 <code>src</code> 改成带前缀的反例）。 <strong>站点字节刻意不列入逐位复现名单</strong>，这条是实测出来的而不是猜的：同一份上游连做两次默认构建， <code>diff -rq</code> 报 7 个 html 全部不同，<code>app.*.js</code>/<code>theme.*.js</code>/<code>@localSearchIndexroot.*.js</code> 三个 chunk 的文件名哈希也换了一遍 —— 本地搜索索引把 <code>lastUpdated</code> 时间打进 chunk 内容，文件名哈希级联跟着变。所以门里那 33 台逐位复现只算 ROM 与截图， 站点的可复现锚在<strong>上游</strong>：<code>tools/gen_site.py</code> 从 <code>docs/scene-port.md</code> 与 <code>evidence/</code> 再生那四个页面，字节层不承诺。</p>`,16)])])}const m=o(a,[["render",n]]);export{h as __pageData,m as default};
